import {TFT_MODULES} from './tft-hardware.js';import {CATALOG} from './core.js';
const frames=new Map();
export function tftDisplay(c){const r=TFT_MODULES[c.type]?.display,s=CATALOG[c.type].scale;if(!r)return '';return `<foreignObject x="${r.x*s}" y="${r.y*s}" width="${r.width*s}" height="${r.height*s}" pointer-events="none"><canvas xmlns="http://www.w3.org/1999/xhtml" data-tft="${c.id}" width="${r.columns}" height="${r.rows}" style="width:100%;height:100%;image-rendering:pixelated;background:#020508" aria-label="${c.id} TFT canlı piksel ekranı"></canvas></foreignObject>`;}
export function updateTFT(packet){for(const[id,d]of Object.entries(packet.tftDevices?.modules||{})){const old=frames.get(id);frames.set(id,{...old,...d,frame:d.frame??old?.frame});}for(const canvas of document.querySelectorAll('[data-tft]')){const d=frames.get(canvas.dataset.tft),key=(d?.revision??-1)+':'+d?.crop+':'+!!d?.visible;if(canvas.dataset.frame===key)continue;canvas.dataset.frame=key;const ctx=canvas.getContext('2d'),img=ctx.createImageData(canvas.width,canvas.height);for(let i=0;i<canvas.width*canvas.height;i++){const v=d?.visible?(d.frame?.[i]??0):0;img.data[i*4]=(v>>11)*255/31;img.data[i*4+1]=((v>>5)&63)*255/63;img.data[i*4+2]=(v&31)*255/31;img.data[i*4+3]=255;}ctx.putImageData(img,0,0);}}
